<?php
declare(strict_types=1); require_once __DIR__.'/includes/bootstrap.php'; $type=(string)($_GET['type']??'expense'); if(!in_array($type,['income','expense'],true))$type='expense'; $title='';$amount='';$category=$type==='income'?'Salary':'Food';$date=date('Y-m-d');$method='Cash';$notes='';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=(string)($_POST['type']??'expense');$title=trim((string)($_POST['title']??''));$amount=trim((string)($_POST['amount']??''));$category=(string)($_POST['category']??'');$date=trim((string)($_POST['transaction_date']??''));$method=(string)($_POST['payment_method']??'Cash');$notes=trim((string)($_POST['notes']??''));
if(!in_array($type,['income','expense'],true))$errors[]='Choose income or expense.';if($title===''||mb_strlen($title)>100)$errors[]='Title is required (maximum 100 characters).';if(!is_numeric($amount)||(float)$amount<=0||(float)$amount>999999999)$errors[]='Amount must be greater than zero.';if(!in_array($category,categories($type),true))$errors[]='Choose a valid category.';if(!valid_date($date))$errors[]='Choose a valid date.';if(!in_array($method,['Cash','Bank transfer','Debit card','Credit card','Mobile wallet','Other'],true))$errors[]='Choose a valid payment method.';if(mb_strlen($notes)>1000)$errors[]='Notes must be 1,000 characters or fewer.';
if(!$errors){$s=$pdo->prepare('INSERT INTO transactions(title,type,category,amount,transaction_date,payment_method,notes) VALUES(:title,:type,:category,:amount,:date,:method,:notes)');$s->execute(['title'=>$title,'type'=>$type,'category'=>$category,'amount'=>number_format((float)$amount,2,'.',''),'date'=>$date,'method'=>$method,'notes'=>$notes]);flash('success',ucfirst($type).' transaction added.');redirect('index.php?month='.substr($date,0,7));}}
$pageTitle='Add transaction — ExpenseWise';require __DIR__.'/includes/header.php';?>
<div class="app-shell"><?php require __DIR__.'/includes/sidebar.php';?><main class="main-area"><header class="topbar"><div><p class="breadcrumb"><a href="index.php">Workspace</a> / Add transaction</p><h1>Give every rupee a place.</h1></div></header><section class="panel form-panel"><span class="eyebrow">TRANSACTION DETAILS</span><h2>Add a transaction</h2><p class="muted">Record income or an expense to keep your monthly picture up to date.</p><?php if($errors):?><div class="notice error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?>
<form method="post" class="transaction-form"><?=csrf_field()?><div class="type-toggle"><label><input type="radio" name="type" value="expense" <?=$type==='expense'?'checked':''?>><span>↑ Expense</span></label><label><input type="radio" name="type" value="income" <?=$type==='income'?'checked':''?>><span>↓ Income</span></label></div><label>Transaction title *<input name="title" maxlength="100" required value="<?=e($title)?>" placeholder="e.g. Grocery shopping"></label><div class="form-grid"><label>Amount (PKR) *<input name="amount" type="number" min="0.01" step="0.01" required value="<?=e($amount)?>" placeholder="0.00"></label><label>Category *<select id="categorySelect" name="category"><?php foreach(categories($type) as $c):?><option <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label></div><div class="form-grid"><label>Date *<input type="date" name="transaction_date" required value="<?=e($date)?>"></label><label>Payment method<select name="payment_method"><?php foreach(['Cash','Bank transfer','Debit card','Credit card','Mobile wallet','Other'] as $m):?><option <?=$method===$m?'selected':''?>><?=e($m)?></option><?php endforeach;?></select></label></div><label>Notes <span class="muted">(optional)</span><textarea name="notes" maxlength="1000" rows="4" placeholder="Add a note…"><?=e($notes)?></textarea></label><div class="form-actions"><button class="button primary">Save transaction →</button><a class="button ghost" href="index.php">Cancel</a></div></form></section><footer class="app-footer">ExpenseWise <span>Personal finance, made clearer.</span></footer></main></div><?php require __DIR__.'/includes/footer.php';?>
